/* Isolated UX demonstrator. No production imports, API calls or real profile data. */
const app = document.querySelector('#app');
const params = new URLSearchParams(location.search);
const storageKey = 'reis400-ux-review-v1-' + (params.get('preview') || 'local');
const paths = {
  home:'M3 11 12 3l9 8M5 10v11h5v-7h4v7h5V10',
  train:'M6 3h12a2 2 0 0 1 2 2v11a3 3 0 0 1-3 3H7a3 3 0 0 1-3-3V5a2 2 0 0 1 2-2ZM4 11h16M8 3v8m8-8v8M8 15h.01M16 15h.01M8 19l-2 3m10-3 2 3',
  profile:'M20 21a8 8 0 0 0-16 0M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',
  trophy:'M8 3h8v7a4 4 0 0 1-8 0ZM8 5H4v3a4 4 0 0 0 4 4m8-7h4v3a4 4 0 0 1-4 4M12 14v6m-5 1h10',
  bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',
  arrow:'M5 12h14m-6-6 6 6-6 6',back:'M19 12H5m6-6-6 6 6 6',
  check:'m5 12 4 4L19 6',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',
  chat:'M4 4h16v12H9l-5 4Z',bag:'M5 7h14v14H5ZM9 7V3h6v4M8 11v6m8-6v6',
  eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Zm13 0a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z',
  shield:'m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6Z',
  info:'M12 11v6m0-10v.1M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',
  alert:'m12 3 10 18H2Zm0 6v5m0 3v.1',pause:'M8 5v14M16 5v14',
  link:'m8 12 8 0M9 7H6a5 5 0 0 0 0 10h3m6-10h3a5 5 0 0 1 0 10h-3',
  spark:'m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5Z',
  wifi:'M3 7a16 16 0 0 1 18 0M6 11a11 11 0 0 1 12 0m-9 4a5 5 0 0 1 6 0m-3 4v.1M2 2l20 20',
};
const icon = (name,size=20) => `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.info}"/></svg>`;
const btn = (label,action,kind='secondary',extra='') => `<button class="btn ${kind}" data-do="${action}" ${extra}>${label}</button>`;
const badge = (label,type='') => `<span class="badge ${type}">${label}</span>`;
const brand = () => `<button class="brand" data-go="home" aria-label="РЕЙС 400 — главная"><span class="brand-mark">//</span><span class="brand-name">РЕЙС<b>400</b><small>ПРАКТИКА НА БОРТУ</small></span></button>`;
const base = () => ({screen:'home',started:false,ready:false,mode:'training',policy:'standard',step:0,loyalty:70,safety:75,promise:false,found:false,bag:'hidden',handoff:'none',returned:false,selected:null,focus:'a',feedback:null,deadline:null,remaining:null,paused:false,criticalError:false,aborted:false,ranking:false,scope:'crew',noticesRead:false,ack:false});
let s=base();
function seed(screen){
  s=base();s.screen=screen;
  if(['home','briefing','profile','ranking','notices','empty'].includes(screen))return;
  s.started=true;s.ready=true;s.step=3;s.loyalty=75;s.safety=80;s.promise=true;s.found=true;s.bag='open';
  if(screen==='inspection'){s.ready=false;s.step=0;s.promise=false;s.found=false;s.bag='hidden';s.loyalty=70;s.safety=75;}
  if(screen==='incident'||screen==='action'){s.focus='b';if(screen==='action')s.selected='clear';}
  if(screen==='feedback'){s.bag='resolved';s.safety=90;s.step=4;s.feedback=feedbackFor('clear',75,80);}
  if(['result','failed'].includes(screen)){s.step=7;s.bag='resolved';s.handoff='completed';s.returned=true;s.loyalty=85;s.safety=90;if(screen==='failed'){s.criticalError=true;s.safety=40;s.bag='failed';}}
  if(['critical','pending','paused','timeout'].includes(screen)){s.step=4;s.found=true;s.bag='critical';s.handoff='accepted';s.safety=65;s.feedback=feedbackFor('wait',75,75);s.feedback.pending=true;s.feedback.next='critical';s.feedback.change='Багаж в проходе потребовал срочного решения: безопасность снизилась на 10. Коллега принял запрос по месту 18, исполнение ещё не проверено.';if(screen==='critical')openCritical(false);if(screen==='paused'){s.remaining=14000;s.paused=true;}if(screen==='timeout'){s.step=5;s.bag='failed';s.safety=40;s.criticalError=true;s.feedback=feedbackFor('timeout',75,65);}}
  if(screen==='offline'){s.focus='b';s.selected='clear';}
}
const initial=params.get('screen')||location.hash.slice(1)||'home';
try{let saved=JSON.parse(sessionStorage.getItem(storageKey));if(saved && (!params.get('screen')||location.hash)){s=saved;}else seed(initial);}catch{seed(initial);}
function save(){try{sessionStorage.setItem(storageKey,JSON.stringify(s));}catch{}}
function go(screen){s.screen=screen;s.selected=null;render();window.scrollTo(0,0);document.querySelector('h1')?.focus({preventScroll:true});}
function knownCount(){return (s.handoff==='completed'?0:1)+(s.found&&s.bag!=='resolved'&&s.bag!=='failed'?1:0);}
function stage(){return `<div class="stage-line"><span class="${s.ready?'':'current'}">01 Приёмка</span><span class="stage-dot"></span><span class="${s.ready&&s.screen!=='result'&&s.screen!=='failed'?'current':''}">02 Обслуживание</span><span class="stage-dot"></span><span class="${s.screen==='result'||s.screen==='failed'?'current':''}">03 Итог</span></div>`;}
function metrics(){return `<div class="metrics" aria-label="Учебные показатели"><div><div class="metric-line"><span class="metric-name">Лояльность пассажиров</span><strong>${s.loyalty} <small>/ 100</small></strong></div><div class="progress" role="meter" aria-label="Лояльность пассажиров" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${s.loyalty}"><span style="width:${s.loyalty}%"></span></div></div><div class="safety"><div class="metric-line"><span class="metric-name">Безопасность</span><strong>${s.safety} <small>/ 100</small></strong></div><div class="progress" role="meter" aria-label="Безопасность" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${s.safety}"><span style="width:${s.safety}%"></span></div></div></div>`;}
function title(kicker,heading,description='',right=''){return `<div class="page-head"><div class="eyebrow">${kicker}</div><div class="head-row"><h1 tabindex="-1">${heading}</h1>${right}</div>${description?`<p>${description}</p>`:''}</div>`;}
const back = (label='К обстановке в вагоне',target='overview')=>`<button class="link-button back" data-go="${target}">${icon('back',18)}${label}</button>`;
function taskA(compact=false){const status={none:'Нужно решение',requested:'Запрос отправлен',accepted:'Коллега принял задачу',completed:'Исполнение проверено'}[s.handoff];return `<button class="task-card ${s.handoff==='completed'?'finished':''}" data-do="open-a"><span class="task-icon">${icon('chat')}</span><span class="grow">${badge(status,s.handoff==='completed'?'green':s.handoff==='none'?'':'violet')}<br><strong>Спор о месте</strong><p>Места 18–19${s.handoff==='accepted'?' · проверьте исполнение':s.handoff==='requested'?' · ждём подтверждения':''}</p></span>${icon(s.handoff==='completed'?'check':'arrow',18)}</button>`;}
function taskB(){if(!s.found)return '';const done=s.bag==='resolved'||s.bag==='failed';return `<button class="task-card ${done?'finished':'urgent'}" data-do="open-b"><span class="task-icon">${icon('bag')}</span><span class="grow">${badge(s.bag==='resolved'?'Выполнено':s.bag==='failed'?'Завершено с ошибкой':s.bag==='critical'?'Критическая ситуация':'Требует внимания',s.bag==='resolved'?'green':s.bag==='failed'||s.bag==='critical'?'red':'amber')}<br><strong>Багаж в проходе</strong><p>${done?'Участок у мест 18–19':'Участок у мест 18–19 · проход сужен'}</p></span>${icon(done?'check':'arrow',18)}</button>`;}
function promiseCard(){return s.promise&&!s.returned?`<div class="promise"><div class="row">${icon('clock',18)}<strong>Вернуться к пассажиру</strong></div><p>Место 18 · вы обещали сообщить решение.</p><p>До конца рабочего шага 7.</p></div>`:'';}
function contextContent(){return `<div class="side-heading">ДРУГИЕ ДЕЛА</div>${s.focus!=='a'?`<div class="compact-task"><strong>Спор о месте</strong><p>${s.handoff==='requested'?'Ожидаем ответа коллеги':s.handoff==='accepted'?'Коллега подтвердил принятие':s.handoff==='completed'?'Исполнение проверено':'Места 18–19 · нужен ответ'}</p></div>`:''}${s.focus!=='b'&&s.found?`<div class="compact-task"><strong>Багаж в проходе</strong><p>${s.bag==='resolved'?'Проход освобождён':s.bag==='failed'?'Завершено с ошибкой':'Требует внимания'}</p></div>`:''}${!s.found&&s.focus==='a'?'<p class="small muted">Других обращений пока нет. Осмотр доступен в обстановке вагона.</p>':''}${promiseCard()}<button class="link-button" data-go="overview">Все известные дела ${icon('arrow',16)}</button>`;}
function contextMobile(){return `<details class="mobile-context"><summary>Другие дела${s.promise&&!s.returned?' · есть обещание':''}</summary><div class="stack tight">${contextContent()}</div></details>`;}
function aside(){return `<aside class="side-context"><div class="panel stack tight">${contextContent()}</div><div class="note">Открытие дела и чтение не расходуют рабочие шаги.</div></aside>`;}
function trainArt(){return `<svg class="train-art" aria-hidden="true" viewBox="0 0 400 240"><defs><linearGradient id="trainPaint" x2="0.2" y2="1"><stop stop-color="#d1c4ec"/><stop offset="1" stop-color="#88769f"/></linearGradient></defs><path d="M5 203h390M5 214h390" stroke="#6a607d" stroke-width="1"/><circle cx="236" cy="110" r="106" fill="none" stroke="#655771" opacity=".45"/><circle cx="236" cy="110" r="81" fill="none" stroke="#655771" opacity=".25"/><path d="M29 171C60 128 139 94 232 91h123c13 0 22 10 22 22v62c0 14-12 22-27 22H37c-14 0-18-11-8-26Z" fill="url(#trainPaint)"/><path d="M72 145c48-27 83-39 125-43l-13 44H72Z" fill="#28283a"/><path d="M220 115h30l-6 29h-30Zm49 0h30l-4 29h-30Zm48 0h30l-2 29h-30Z" fill="#343046"/><path d="M31 172h346" stroke="#604e79" stroke-width="5"/><path d="M28 184h346" stroke="#eee8f9" stroke-opacity=".35"/><text x="227" y="72" font-family="Segoe UI,Arial" font-size="11" fill="#c4b8d6" letter-spacing="4">РЕШЕНИЯ НА БОРТУ</text></svg>`;}
function home(){return `${title('Практика на борту','Ваш учебный рейс')}<section class="home-hero"><div class="hero-copy">${badge(s.started?'Можно продолжить':'Обучение','violet')}<h2>${s.started?'Продолжим рейс?':'Один вагон.<br>Несколько решений.'}</h2><p>${s.started?'Вернитесь к сохранённым делам и обещаниям.':'Осмотрите вагон, помогите пассажирам и разберите результат.'}</p>${btn((s.started?'Продолжить рейс':'Начать учебный рейс')+icon('arrow',18),s.started?'resume':'brief','primary')}<small class="muted">Чтение без таймера. Режим выберете перед началом.</small></div>${trainArt()}</section><details class="home-secondary"><summary>Другие возможности</summary><div class="stack"><section class="panel"><h3>Цель недели</h3><p class="small muted">Пройти один рейс и открыть разбор. Пропуск дня не обнуляет прогресс.</p></section><button class="practice-card" data-go="profile"><span class="feature-icon">${icon('profile')}</span><span><h3>Мой прогресс</h3><p>Навыки, история и рекомендации</p></span>${icon('arrow',18)}</button><div class="stack tight"><h3>Точечная практика</h3><button class="practice-card" data-do="practice"><span class="feature-icon">${icon('chat')}</span><span><h3>Разговор с пассажиром</h3><p>Обращение и следующий шаг</p></span>${icon('arrow',18)}</button><button class="practice-card" data-do="practice-b"><span class="feature-icon">${icon('eye')}</span><span><h3>Наблюдение и приоритеты</h3><p>Известные факты и порядок действий</p></span>${icon('arrow',18)}</button></div></div></details>`;}
function briefing(){return `${back('На главную','home')}${title('Перед началом','Ваш учебный рейс','Одна зона вагона. Сначала приёмка, затем работа с пассажирами.')}<div class="two-col"><div class="stack"><section class="panel stack"><h2>Как хотите пройти?</h2><div class="radio-grid"><label class="radio-card"><input type="radio" name="mode" value="training" ${s.mode==='training'?'checked':''}><span><strong>Обучение</strong><small>Объяснения после действий и учебная пауза. Без рейтинга.</small></span></label><label class="radio-card"><input type="radio" name="mode" value="assessment" ${s.mode==='assessment'?'checked':''}><span><strong>Проверка себя</strong><small>Самостоятельные решения. Подробный разбор в конце, паузы нет.</small></span></label></div><div><label class="setting-label" for="timing">Время для срочного решения</label><select id="timing" name="policy"><option value="standard" ${s.policy==='standard'?'selected':''}>Обычное — 20 секунд</option><option value="extended" ${s.policy==='extended'?'selected':''}>Увеличенное — 200 секунд</option><option value="untimed" ${s.policy==='untimed'?'selected':''}>Без ограничения</option></select><p class="small muted" style="margin-top:12px">Обычное чтение всегда без таймера. В срочном окне время продолжается при закрытии вкладки.</p></div>${s.mode==='assessment'?`<label class="radio-card"><input id="rank-opt" type="checkbox" ${s.ranking?'checked':''}><span><strong>Участвовать в рейтинге недели</strong><small>Добровольно. Две попытки на задание. Сравнение только в своей группе времени.</small></span></label>`:''}${btn('Перейти к приёмке '+icon('arrow',18),'begin','primary full')}</section></div><aside class="panel stack"><h3>Три простых правила</h3><ol class="bullet-list"><li>Читайте обстановку и открывайте известные дела.</li><li>Каждое рабочее действие меняет ситуацию.</li><li>Проверьте результат и вернитесь к обещанному.</li></ol><div class="note">В прототипе показан один авторский пример. Условия классов обслуживания требуют отдельного содержания.</div></aside></div>`;}
function inspection(){return `${back('К подготовке','briefing')}${title('Учебный рейс · вагон 4','Проверьте готовность')}${stage()}${metrics()}<div class="compact"><section class="panel stack"><div class="world-location">${icon('train',18)}Приёмка вагона</div><h2>Сверьте карточку готовности</h2><p>В учебной карточке указаны доступные сервисы и ответственный сотрудник. Эти сведения понадобятся при обращении пассажира.</p><details><summary>Карточка учебного вагона</summary><div class="stack tight"><p class="small">Вагон 4 · сидячий салон. При несоответствии размещения сверьте билет и передайте запрос ответственному коллеге.</p><p class="small muted">Синтетические условия упражнения, без имитации официального допуска поезда.</p></div></details>${btn('Сверить сведения и принять вагон','ready','primary full')}<p class="small muted">Рабочее действие · 1 шаг. Проверка будет отмечена в разборе.</p></section></div>`;}
function overview(){const allDone=s.handoff==='completed'&&(s.bag==='resolved'||s.bag==='failed')&&s.returned;return `${title('Учебный рейс · вагон 4','Обстановка в вагоне','',badge('Шаг '+s.step+' / 16','outline'))}${stage()}${metrics()}<div class="two-col"><div><section class="panel world"><div class="world-location">${icon('train',18)}Салон · места 18–19</div><p class="world-story">${allDone?'Пассажир получил ответ. Работа с известными делами завершена. Можно перейти к разбору рейса.':s.bag==='resolved'?'Проход свободен. Пассажир на месте 18 ещё ждёт, когда вы вернётесь с решением по его обращению.':s.found?'У мест 18–19 остаётся спор о размещении. Рядом багаж сужает проход. Пассажир ожидает вашего возвращения.':'Пассажир у места 18 просит проверить размещение. В салоне негромко разговаривают. Отсюда проход виден не полностью.'}</p><div class="world-footer">${btn(allDone?'Открыть итог рейса '+icon('arrow',18):icon('eye',18)+' Осмотреть салон · 1 шаг',allDone?'finish':'inspect',allDone?'primary':'secondary')}</div></section><div class="section-heading"><h2>${allDone?'Завершённые дела':'Известные дела'}</h2><span class="section-no">${allDone?'2':knownCount()+' открыто'}</span></div><div class="task-list">${s.found&&s.bag==='open'?taskB()+taskA():taskA()+taskB()}</div></div><aside class="stack"><section class="panel stack tight"><div class="side-heading">НЕ ЗАБЫТЬ</div>${promiseCard()||'<p class="small muted">Здесь появятся ваши обещания пассажирам.</p>'}<div class="divider"></div><h3>Следующий шаг — ваш</h3><p class="small muted">Открытое дело сохраняется, когда вы возвращаетесь к обстановке.</p></section><details><summary>Как идёт время</summary><div class="small muted">Обычное действие расходует один рабочий шаг. Срочный таймер включается только при открытии критической сцены.</div></details></aside></div><div class="row" style="margin-top:24px">${btn('Сохранить и выйти к главной','leave','ghost')}${btn('Завершить досрочно','abort','ghost')}</div>`;}
function options(){
 if(s.focus==='b')return s.bag==='resolved'||s.bag==='failed'?[]:[{id:'clear',title:'Организовать освобождение прохода',desc:'Обратиться к владельцу багажа и проверить результат.'},{id:'defer',title:'Сначала закончить разговор о месте',desc:'Оставить багаж и вернуться к обращению пассажира.'}];
 if(s.handoff==='completed')return [];
 if(s.handoff==='accepted')return [{id:'return',title:'Проверить исполнение и вернуться к пассажиру',desc:'Уточнить результат у коллеги и сообщить его пассажиру на месте 18.'}];
 if(s.handoff==='requested')return [{id:'wait',title:'Дождаться ответа коллеги',desc:'Получить подтверждение, что запрос принят.'},{id:'inspect',title:'Осмотреть салон',desc:'Пока запрос обрабатывается, проверить видимую обстановку.'}];
 return [...(!s.promise?[{id:'promise',title:'Признать обращение и обещать вернуться',desc:'Дать пассажиру понять, что его вопрос принят.'}]:[]),{id:'handoff',title:'Сверить билеты и запросить коллегу',desc:'Уточнить размещение и передать конкретный запрос.'},{id:'inspect',title:'Сначала осмотреть салон',desc:'Проверить обстановку вокруг, затем продолжить разговор.'}];
}
function incident(){const opts=options();const b=s.focus==='b';return `${back()}${title('Вагон 4 · места 18–19',b?'Багаж в проходе':'Спор о месте','',badge(b?(s.bag==='resolved'?'Выполнено':'Требует внимания'):'Обращение пассажира',b&&s.bag!=='resolved'?'amber':'violet'))}${metrics()}${contextMobile()}<div class="two-col"><div><section class="panel"><div class="speaker"><span class="avatar">${icon(b?'eye':'chat',18)}</span><div>${b?'Ваше наблюдение':'Пассажир · место 18'}<small>${b?'После осмотра салона':'Обращение остаётся открытым'}</small></div></div><p class="quote">${b?(s.bag==='resolved'?'Багаж размещён, проход свободен. Вы проверили результат.':'Чемодан сужает проход. Пассажиры обходят его боком.'):(s.handoff==='accepted'?'Коллега ответил: «Запрос принял». Пассажир ещё не знает решения.':s.handoff==='requested'?'Вы отправили запрос коллеге. Подтверждения пока нет.':s.handoff==='completed'?'Вы проверили решение и сообщили его пассажиру. Обращение завершено.':'«Проверьте, пожалуйста, наше место. У нас с соседом разные данные».')}</p>${s.promise&&!b&&!s.returned?'<div class="facts">'+badge('Вы обещали вернуться','violet')+'</div>':''}</section>${opts.length?`<div class="decision-intro"><h2>Что будете делать?</h2></div><p class="pace">Без таймера · каждое действие расходует 1 шаг</p><div class="choices" role="group" aria-label="Варианты действия">${opts.map(o=>`<button class="choice ${s.selected===o.id?'selected':''}" data-select="${o.id}" aria-pressed="${s.selected===o.id}"><span class="choice-radio" aria-hidden="true"></span><span><strong>${o.title}</strong><small>${o.desc}</small></span></button>`).join('')}</div><div class="action-area"><p>${s.selected?'Выбранное действие изменит обстановку.':'Сначала выберите действие.'}</p>${btn('Выполнить действие '+icon('arrow',18),'commit','primary',s.selected?'':'disabled')}</div>`:btn('Вернуться к обстановке '+icon('arrow',18),'overview','primary full','style="margin-top:24px"')}</div>${aside()}</div>`;}
function feedbackFor(action,oldL,oldS){const data={
ready:['Готовность проверена','Вы сверили учебную карточку вагона. Данные о сервисе доступны для дальнейших решений.','Пассажир у места 18 обратился за помощью.','Проверка перед обслуживанием позволяет использовать подтверждённые сведения.'],
promise:['Пассажир знает, что вы вернётесь','Вы приняли обращение и обещали сообщить решение.','В делах появилось обещание вернуться к пассажиру на месте 18.','Обещание — отдельная обязанность. Закрытие другого дела не выполнит её автоматически.'],
inspect:['Осмотр добавил новый факт','Вы заметили багаж у мест 18–19. Он сужает проход.','Появилось новое известное дело: «Багаж в проходе». Обращение пассажира сохранилось.','Наблюдение помогает расставить приоритеты до ухудшения ситуации.'],
clear:['Проход снова свободен','Вы организовали размещение багажа и проверили, что он больше не мешает проходу.','Обращение у места 18 остаётся открытым. Вы обещали вернуться.','После действия важно проверить результат. Решённая проблема больше не ухудшается.'],
handoff:['Запрос отправлен коллеге','Вы сверили данные и передали коллеге конкретный вопрос по размещению.','Дело ожидает подтверждения. Передача ещё не завершена.','Запрос, принятие и исполнение — три разных события. Не закрывайте дело до проверки.'],
wait:['Коллега принял задачу','Вы получили подтверждение: коллега работает над вопросом размещения.','Осталось проверить исполнение и сообщить решение пассажиру.','Подтверждение принятия не означает, что пассажир уже получил помощь.'],
return:['Пассажир получил ответ','Вы проверили исполнение у коллеги и вернулись к пассажиру на месте 18.','Обращение и ваше обещание завершены.','Адресный возврат замыкает цикл помощи: принять, выполнить, проверить, сообщить.'],
defer:['Вы вернулись к обращению','Багаж остался в проходе. Работа над ним не выполнена.','Обстановка изменилась после рабочего действия.','Отложенное дело сохраняется и может потребовать срочного решения.'],
timeout:['Время для решения истекло','Срочное действие не было выполнено в отведённое время.','Ситуация завершена с критической ошибкой. Остальные дела и обещание сохраняются.','Поздний ответ не отменяет истечение срока. Можно закончить учебные действия и изучить разбор.'],
unsafe:['Проход остался заблокирован','Вы отложили обеспечение прохода в критической ситуации.','Критическая ошибка сохранена. Зачёт этой попытки уже недоступен.','Успешное решение другой задачи не компенсирует критическую ошибку.'],
};let a=data[action]||data.inspect;return {action,title:a[0],text:a[1],change:a[2],why:a[3],oldL,oldS,next:'overview',pending:false};}
function feedback(){const f=s.feedback||feedbackFor('clear',75,80);const pending=f.pending||s.screen==='pending';const dl=s.loyalty-f.oldL,ds=s.safety-f.oldS;const delta=n=>(n>0?'+':'')+n;return `${title('Учебный рейс · результат действия',f.title)}<div class="two-col"><section class="panel"><div class="feedback-icon ${s.criticalError?'warning':''}">${icon(s.criticalError?'alert':'check',28)}</div><p class="world-story">${f.text}</p><div class="impact-row"><div class="impact"><span class="small muted">Лояльность пассажиров</span><strong>${f.oldL} → ${s.loyalty}<span>${delta(dl)} за шаг</span></strong></div><div class="impact"><span class="small muted">Безопасность</span><strong>${f.oldS} → ${s.safety}<span class="${ds<0?'critical-text':''}">${delta(ds)} за шаг</span></strong></div></div><div class="changed-world"><strong>Что ещё изменилось</strong><p class="muted">${f.change}</p></div>${s.mode==='training'?`<div class="teaching" style="margin-top:20px"><strong>Почему это имеет значение</strong><p>${f.why}</p></div>`:'<p class="small muted" style="margin-top:20px">Подробный разбор решения появится в итоге рейса.</p>'}${s.criticalError?'<div class="banner" style="margin-top:20px">'+icon('alert')+'Нужна практика. Критическая ошибка сохранится в итоге.</div>':''}${pending?`<div class="pending-alert" style="margin-top:24px"><div class="row">${icon('alert')}<strong>Из салона поступил срочный сигнал</strong></div><p class="small muted">Следующая сцена потребует решения${s.policy==='untimed'?' без ограничения времени':s.policy==='extended'?' за 200 секунд':' за 20 секунд'}. Отсчёт ещё не начался.</p>${btn('Перейти к срочной ситуации '+icon('arrow',18),'critical-start','primary full')}</div>`:`<div class="action-area"><p>Можно спокойно прочитать результат.</p>${btn('К обстановке в вагоне '+icon('arrow',18),'overview','primary')}</div>`}</section><aside class="panel stack"><div class="side-heading">РЕЙС ПРОДОЛЖАЕТСЯ</div><h3>Шаг ${s.step} / 16</h3><p class="small muted">${s.returned?'Обещание выполнено.':s.promise?'Обещание вернуться к пассажиру сохраняется.':'Открытые дела доступны в общей обстановке.'}</p>${promiseCard()}</aside></div>`;}
function critical(){return `${title('Срочная ситуация · вагон 4','Нужен свободный проход')}<div class="critical-banner" role="region" aria-label="Срочное решение"><div><strong>${icon('alert',16)} Критическая ситуация</strong><p class="small muted">${s.policy==='untimed'?'Без ограничения · учебная адаптация':'Время идёт, даже если закрыть вкладку.'}</p></div><div class="timer"><span id="timer">${s.policy==='untimed'?'∞':seconds()}</span><small>${s.policy==='untimed'?'без таймера':'секунд осталось'}</small></div></div>${metrics()}<div class="compact"><div class="panel"><p class="world-story">Пассажир споткнулся о багаж. Проход остаётся заблокированным, рядом собираются люди.</p><p class="story-note">Коллега уже принял запрос по месту 18. К нему можно вернуться после срочного решения.</p></div><div class="decision-intro"><h2>Что сделаете сейчас?</h2></div><p class="pace">Нажатие сразу выполняет действие.</p><div class="choices critical-actions"><button class="choice" data-do="critical-safe"><span class="grow"><strong>Организовать освобождение прохода</strong><small>Обратиться к владельцу, подключить помощь и проверить проход.</small></span>${icon('arrow',18)}</button><button class="choice" data-do="critical-unsafe"><span class="grow"><strong>Сначала закончить вопрос размещения</strong><small>Вернуться к пассажиру и отложить действия с багажом.</small></span>${icon('arrow',18)}</button></div>${s.mode==='training'?`<div class="row" style="margin-top:20px">${btn(icon('pause',18)+' Учебная пауза','pause','secondary')}${btn('Подсказка','hint','ghost')}</div>`:'<p class="small muted" style="margin-top:20px">Проверка себя · учебной паузы нет. '+btn('Прервать попытку','abort','ghost')+'</p>'}<p class="note">Остальные дела сохранены. Несвязанные рабочие действия временно недоступны.</p></div>`;}
function paused(){return `${title('Обучение · пауза','Можно сделать перерыв')}<div class="compact panel stack"><div class="feedback-icon">${icon('pause',28)}</div><h2>Срочное окно на паузе</h2><p class="muted">Остаток: ${s.policy==='untimed'?'без ограничения':Math.ceil((s.remaining||14000)/1000)+' секунд'}. Продолжение не выдаст новый полный таймер.</p>${s.hint?'<div class="teaching"><strong>Подсказка</strong><p>Оцените, какое из известных дел сейчас связано с безопасностью прохода.</p></div>':''}${btn('Продолжить с оставшимся временем','unpause','primary')}<p class="small muted">Здесь показана учебная пауза прототипа. В реализации её подтверждает сервер.</p></div>`;}
function result(){const failed=s.criticalError||s.screen==='failed';const early=s.safety>=85&&!failed;const total=s.policy==='untimed'?(early?6:5):(failed?5:early?7:6);return `${title('Итог учебного рейса',failed?'Есть решения для повторной практики':'Рейс завершён. Вы справились.','Вагон 4 · '+(s.mode==='training'?'обучение':'проверка себя')+' · '+(s.policy==='untimed'?'без таймера':s.policy==='extended'?'увеличенное время':'обычное время'),badge(failed?'Нужна практика':'Зачёт',failed?'red':'green'))}${metrics()}${failed?'<div class="banner" style="margin-bottom:24px">'+icon('alert')+'Критическая ошибка: срочное действие не выполнено безопасно. Другие успехи сохранены.</div>':''}<div class="two-col"><div class="stack"><section class="panel"><div class="between"><h2>Что получилось</h2><span class="score-number">${total}<small class="muted"> / ${s.policy==='untimed'?6:7}</small></span></div><p class="small muted" style="margin-top:12px">Учебные критерии этой попытки</p><div class="criteria">${[['Проверили готовность вагона','Приёмка выполнена до обслуживания',true],['Заметили ситуацию при осмотре',early?'Багаж обнаружен до срочного сигнала':'Ситуация раскрылась после срочного сигнала',early],['Сверили документы и приняли обращение','Есть наблюдения по регламенту и эмпатии',true],['Проверили передачу и вернулись','Коллега подтвердил принятие; пассажир получил ответ',true],['Обеспечили безопасный проход',s.policy==='untimed'?'Срок не оценивается при выбранном режиме':failed?'Сохранена критическая ошибка':'Действие выполнено в допустимое время',!failed]].map(([a,b,ok])=>`<div class="criterion"><span><strong>${a}</strong><small>${b}</small></span><span class="${ok?'check':'critical-text'}">${icon(ok?'check':'alert',18)}</span></div>`).join('')}</div></section><details><summary>Как ваши решения изменили рейс</summary><div><ol class="timeline">${[['Приёмка','Сведения о вагоне проверены.'],['Обращение пассажира','Появилось обещание вернуться к месту 18.'],[early?'Осмотр и освобождение прохода':'Срочная ситуация с багажом',failed?'Срок истёк или действие отложено.':early?'Багаж обнаружен до ухудшения.':'Проход освобождён после сигнала.'],['Запрос → подтверждение → исполнение','Каждый этап передачи проверен отдельно.'],['Адресный возврат','Пассажир на месте 18 получил решение.']].map(([a,b],i)=>`<li><span class="timeline-number">${i+1}</span><div><strong>${a}</strong><p>${b}</p></div></li>`).join('')}</ol></div></details><div class="row">${btn(failed?'Повторить срочную ситуацию':'Попробовать другой порядок','retry','primary')}${btn('Открыть профиль','profile','secondary')}</div></div><aside class="stack"><section class="panel stack"><h3>Рекомендуемая практика</h3><p class="muted small">${failed?'Потренируйте приоритеты в срочной ситуации. Исходная попытка останется в истории.':'В следующей попытке начните с другого известного дела и сравните последствия.'}</p><div class="divider"></div><div class="between"><span>Опыт практики</span><strong class="accent">${s.ack?'+20 XP':'После разбора'}</strong></div><p class="small muted">За первую полную практику этого задания за неделю. Повтор не удваивает опыт.</p><div class="between"><span>Рейтинг недели</span><strong>${s.mode==='assessment'&&s.ranking?(failed?'0':early?'100':'85')+' СП':'Без участия'}</strong></div></section><div class="note">Учебные критерии, XP и сезонные очки показываются отдельно. Это не оценка профессиональной пригодности.</div></aside></div>`;}
function aborted(){return `${title('Итог учебного рейса','Попытка завершена досрочно','Пройденные шаги доступны для разбора.',badge('Прервано','amber'))}${metrics()}<div class="compact panel stack"><h2>Остались незавершённые дела</h2><p class="muted">Попытка не зачтена. Досрочное завершение само по себе не означает критическую ошибку.</p>${s.criticalError?'<div class="banner">В этой попытке также была критическая ошибка.</div>':''}<div class="between"><span>Опыт практики</span><strong>0 XP</strong></div><div class="between"><span>Сезонные очки</span><strong>0 СП</strong></div>${btn('Начать новую практику','retry','primary')}${btn('На главную','leave','secondary')}</div>`;}
function profile(empty=false){return `${title('Мой профиль','Ваш прогресс','Результаты практики и конкретные наблюдения по навыкам.')}<div class="panel between" style="margin-bottom:24px"><div class="row"><span class="avatar">П</span><div><h3>Проводник-018</h3><p class="small muted">Бригада М-01 · учебный профиль</p></div></div>${badge('Демо','outline')}</div>${empty?`<div class="status-empty">${icon('spark',32)}<h2>Первая практика ещё впереди</h2><p class="muted">Без попыток навыки показываются как «не оценено». Ваши результаты появятся после разбора.</p>${btn('Начать учебный рейс','brief','primary')}</div>`:`<div class="two-col"><div class="stack"><section class="panel"><div class="between"><h2>Наблюдения по навыкам</h2>${badge('Обучение','violet')}</div><p class="small muted" style="margin-top:12px">Последняя попытка · 26 сентября · обычное время</p>${[['Эмпатия','1 / 1','Признали обращение пассажира',100],['Работа по регламенту','3 / 3','Приёмка, осмотр и проверка документов',100],['Взаимодействие с экипажем','2 / 2','Подтвердили передачу и вернулись',100],['Своевременность действий','1 / 1','Обеспечили проход в допустимый срок',100]].map(([a,b,c,d])=>`<div class="skill-row"><div class="between"><strong>${a}</strong><span class="accent no-wrap">${b}</span></div><p class="small muted">${c}</p></div>`).join('')}<button class="link-button" data-do="history">Открыть разбор этой попытки ${icon('arrow',16)}</button></section><section class="panel"><h2>История рейсов</h2><button class="practice-card" data-do="history" style="border:0;padding:20px 0 0"><span class="feature-icon">${icon('train')}</span><span><h3>Один вагон, несколько задач</h3><p>26 сентября · обучение · зачёт</p></span>${icon('arrow',18)}</button></section></div><aside class="stack"><section class="panel stack tight"><h3>Уровень практики 1</h3><div class="pill-stat"><div><strong>20 <small>XP</small></strong><small>из 100 до уровня 2</small></div></div><div class="progress"><span style="width:20%"></span></div><p class="small muted">Опыт за завершённую практику с разбором.</p></section><section class="panel stack tight"><h3>Достижения</h3><div class="row"><span class="feature-icon">${icon('link')}</span><span>Замкнули цикл помощи<small class="muted" style="display:block">Приняли → проверили → вернулись</small></span></div></section><section class="panel stack tight"><h3>Что попробовать дальше</h3><p class="small muted">Поменять порядок действий и сравнить итог.</p>${btn('Начать практику','retry','secondary full')}</section></aside></div>`}<details style="margin-top:24px"><summary>Настройки учебного профиля</summary><div class="stack tight"><p class="small muted">В прототипе нет личных данных. В приложении здесь будут управление данными и выход с пояснением последствий.</p>${btn('Посмотреть состояние без попыток','empty','secondary')}</div></details><p class="footer-note">Демонстрационные данные. В реальном профиле дата, режим и версия разбора привязаны к конкретной попытке.</p>`;}
function ranking(){const rows=s.scope==='crew'?[['Проводник-042',100],['Проводник-018',85],['Проводник-027',71]]:s.scope==='depot'?[['Проводник-063',100],['Проводник-042',100],['Проводник-018',85],['Проводник-071',71]]:[['Проводник-096',100],['Проводник-063',100],['Проводник-042',100],['Проводник-018',85]];return `${title('Добровольное соревнование','Рейтинг недели','21–27 сентября · один общий учебный рейс',badge('Демо-данные','outline'))}<div class="two-col"><div class="stack"><div class="banner">${icon('info')}<span class="small">Один пакет заданий и одна группа времени. XP здесь не учитывается.</span></div><div class="tabs" aria-label="Область рейтинга">${[['crew','Бригада'],['depot','Депо'],['company','Компания']].map(([id,l])=>`<button class="tab ${s.scope===id?'active':''}" data-scope="${id}" aria-pressed="${s.scope===id}">${l}</button>`).join('')}</div><section class="panel" style="padding:8px"><table class="leader-table"><caption class="sr-only">Демонстрационный рейтинг ${s.scope}, сезонные очки</caption><thead><tr><th>Место</th><th>Участник</th><th>СП</th></tr></thead><tbody>${rows.map(([n,p],i)=>`<tr class="${n==='Проводник-018'?'me':''}"><td>${p===100?1:i+1}</td><td>${n}${n==='Проводник-018'?'<span class="you">Вы · пример участия</span>':''}</td><td><strong>${p}</strong></td></tr>`).join('')}</tbody></table></section><details><summary>Как считаются места</summary><div class="small muted">Лучший допустимый результат из двух попыток за задание. При равных очках — общее место. Критическая ошибка даёт 0 СП. Новая неделя не обнуляет XP и историю.</div></details></div><aside class="panel stack"><h3>${s.ranking?'Участие включено':'Участие — по желанию'}</h3><p class="small muted">${s.ranking?'Соревновательную попытку выбираете до её начала.':'Можно учиться и сохранять прогресс без соревнования.'}</p>${btn(s.ranking?'Не участвовать дальше':'Включить участие','opt-in',s.ranking?'secondary':'primary')}<div class="divider"></div><span class="small muted">Группа примера</span><strong>Обычное время · новички</strong><p class="small muted">Доступно до 2 попыток на задание. Практика остаётся доступной после лимита.</p></aside></div>`;}
function notices(){return `${title('Важное для вас','Уведомления','Учебные обновления собраны здесь, чтобы не прерывать решение.')}<div class="between" style="margin-bottom:20px">${badge(s.noticesRead?'Всё прочитано':'2 новых','violet')}${btn('Прочитать всё','read-all','secondary')}</div><section class="panel">${[['spark','Цикл помощи завершён','Вы проверили результат и вернулись к пассажиру. Достижение добавлено в профиль.','profile'],['train','Доступна новая практика','Попробуйте иной порядок действий в знакомой обстановке.','briefing']].map(([ic,t,d,to])=>`<div class="notice-row"><span class="feature-icon">${icon(ic)}</span><div><span class="small muted">Сегодня</span><h3>${t}</h3><p>${d}</p><button class="link-button" data-go="${to}">Открыть ${icon('arrow',16)}</button></div></div>`).join('')}</section>`;}
function offline(){return `${back()}${title('Состояние соединения','Не удалось подтвердить действие')}<div class="compact panel stack"><div class="feature-icon">${icon('wifi',24)}</div><h2>Проверяем, принят ли ваш выбор</h2><p class="muted">Вы выбрали «Организовать освобождение прохода». Ответ не получен. Повторная отправка сохранит тот же запрос.</p><div class="banner"><span class="small">Если срочный таймер уже был открыт, отсутствие связи не останавливает срок.</span></div>${btn('Проверить состояние и восстановить','recover','primary')}<small class="muted">Это макет восстановления связи. Он показывает заранее подготовленный подтверждённый результат.</small></div>`;}
const gameScreens=['inspection','overview','incident','action','feedback','pending','critical','paused','timeout','offline'];
function render(){
 document.body.dataset.screen=s.screen;
 const af=document.activeElement;const focusKey=af?.dataset?.scope?'[data-scope="'+af.dataset.scope+'"]':af?.dataset?.do?'[data-do="'+af.dataset.do+'"]':af?.name==='mode'?'input[name="mode"][value="'+af.value+'"]':null;
 const locked=s.screen==='critical'||s.screen==='paused';const game=gameScreens.includes(s.screen);const current=['profile','empty'].includes(s.screen)?'profile':s.screen==='ranking'?'ranking':'home';
 const screens={home,briefing,inspection,overview,incident,action:incident,feedback,pending:feedback,critical,paused,timeout:feedback,result,failed:result,aborted,profile,empty:()=>profile(true),ranking,notices,offline};
 const nav=[['home','home','Главная'],['profile','profile','Профиль'],['ranking','trophy','Рейтинг']];
 const content=(screens[s.screen]||home)();
 app.innerHTML=`<div class="shell"><aside class="rail">${locked?'<div class="brand-name">РЕЙС<b>400</b></div>':brand()}<nav class="rail-nav" aria-label="Главное меню">${nav.map(([id,ic,l])=>`<button class="nav-item ${current===id?'active':''}" data-go="${id}" ${locked?'disabled':''} ${current===id?'aria-current="page"':''}>${icon(ic)}${l}</button>`).join('')}${s.started&&!locked?`<button class="nav-item" data-do="resume">${icon('train')}Текущий рейс</button>`:''}</nav><div class="rail-footer"><div class="row"><span class="avatar">П</span><div><strong class="small">Проводник-018</strong><p class="small muted">Бригада М-01</p></div></div><span class="proto-label">UX-концепция · демо-данные</span></div></aside><div class="work"><header class="topbar">${locked?'<span class="brand-name">РЕЙС<b>400</b></span>':brand()}<span class="top-note">${game?'Учебный рейс · '+(s.mode==='training'?'обучение':'проверка себя'):'Тренажёр решений для проводников'}</span>${locked?badge('Решение в фокусе','red'):`<button class="notification-link" data-go="notices" aria-label="Уведомления${s.noticesRead?'':', 2 новых'}">${icon('bell',18)}<span class="notification-text">Уведомления</span>${s.noticesRead?'':'<span class="notification-dot"></span>'}</button>`}</header><main id="main" class="main ${game?'game':''}">${content}<footer class="footer-note"><span class="proto-label">Прототип для обсуждения · решения сохраняются только в этой вкладке</span></footer></main></div>${!game?`<nav class="bottom-nav" aria-label="Нижнее меню">${nav.map(([id,ic,l])=>`<button class="${current===id?'active':''}" data-go="${id}" ${current===id?'aria-current="page"':''}>${icon(ic,20)}${l}</button>`).join('')}</nav>`:''}</div>`;
 if(focusKey)app.querySelector(focusKey)?.focus({preventScroll:true});
 history.replaceState(null,'','#'+s.screen);save();
 try{parent.postMessage({type:'reis400-screen',screen:s.screen},location.origin==='null'?'*':location.origin);}catch{}
 if(s.screen==='critical')tick();
}
function afterWork(action){
 const oldL=s.loyalty,oldS=s.safety;s.step++;
 if(action==='ready'){s.ready=true;s.started=true;}
 if(action==='promise'){s.promise=true;s.loyalty+=5;}
 if(action==='inspect'){if(!s.found){s.found=true;s.bag='open';s.safety+=5;}}
 if(action==='clear'){s.bag='resolved';s.safety+=10;}
 if(action==='handoff'){s.handoff='requested';s.requestedStep=s.step;}
 if(action==='wait'){s.handoff='accepted';}
 if(action==='return'){s.handoff='completed';s.returned=true;s.loyalty+=10;}
 if(s.handoff==='requested'&&s.step>(s.requestedStep||3))s.handoff='accepted';
 s.feedback=feedbackFor(action,oldL,oldS);
 if(action==='inspect'&&oldS===s.safety){s.feedback.title='Обстановка проверена';s.feedback.text=s.bag==='resolved'?'Проход остаётся свободным. Новых признаков нет.':'Известный багаж остаётся в проходе.';s.feedback.change='Открытые дела сохранились.';}
 if(s.step>=4&&s.bag!=='resolved'&&s.bag!=='failed'){s.found=true;s.bag='critical';s.safety-=10;s.feedback.pending=true;s.feedback.next='critical';s.feedback.change=(s.handoff==='accepted'?'Коллега принял запрос по месту 18. ':'Другие известные дела сохранились. ')+'Из салона поступил срочный сигнал.';}
 if(s.promise&&!s.returned&&s.step>=7&&!s.promiseMissed){s.promiseMissed=true;s.loyalty-=15;s.feedback.change+=' Срок обещания пассажиру пропущен (−15 лояльности).';}
 s.selected=null;go('feedback');
}
function openCritical(draw=true){s.screen='critical';s.deadline=s.policy==='untimed'?null:Date.now()+(s.policy==='extended'?200000:20000);s.paused=false;if(draw){render();window.scrollTo(0,0);}}
function seconds(){return String(Math.max(0,Math.ceil(((s.deadline||Date.now())-Date.now())/1000))).padStart(2,'0');}
function resolveCritical(action){if(s.deadline&&Date.now()>=s.deadline)action='timeout';let oldL=s.loyalty,oldS=s.safety;s.step++;s.deadline=null;s.paused=false;if(action==='clear'){s.safety+=10;s.bag='resolved';}else{s.criticalError=true;s.bag='failed';s.safety-=action==='timeout'?25:30;}s.feedback=feedbackFor(action,oldL,oldS);go(action==='timeout'?'timeout':'feedback');document.querySelector('#announcement').textContent=s.feedback.title;}
function tick(){if(s.screen!=='critical'||s.policy==='untimed')return;if(Date.now()>=s.deadline){resolveCritical('timeout');return;}let el=document.getElementById('timer');if(el)el.textContent=seconds();}
setInterval(tick,200);
function handle(action){
 if(action==='brief'){s=base();go('briefing');}
 else if(action==='begin'){s.started=true;s.ready=false;s.step=0;s.loyalty=70;s.safety=75;go('inspection');}
 else if(action==='ready')afterWork('ready');
 else if(action==='resume'){if(s.paused)go('paused');else if(s.bag==='critical'&&s.deadline){s.screen='critical';render();}else if(s.feedback?.pending)go('pending');else go(s.ready?'overview':'inspection');}
 else if(action==='leave')go('home');
 else if(action==='overview')go('overview');
 else if(action==='open-a'){s.focus='a';go('incident');}
 else if(action==='open-b'){s.focus='b';go('incident');}
 else if(action==='inspect')afterWork('inspect');
 else if(action==='commit'&&s.selected)afterWork(s.selected);
 else if(action==='critical-start')openCritical();
 else if(action==='critical-safe')resolveCritical('clear');
 else if(action==='critical-unsafe')resolveCritical('unsafe');
 else if(action==='pause'||action==='hint'){s.remaining=s.policy==='untimed'?null:Math.max(0,s.deadline-Date.now());s.deadline=null;s.paused=true;s.hint=action==='hint';go('paused');}
 else if(action==='unpause'){s.deadline=s.policy==='untimed'?null:Date.now()+s.remaining;s.paused=false;go('critical');}
 else if(action==='finish'){s.ack=true;go(s.criticalError?'failed':'result');}
 else if(action==='profile')go('profile');
 else if(action==='empty')go('empty');
 else if(action==='history'){seed('result');s.ack=true;render();window.scrollTo(0,0);}
 else if(action==='retry'){s=base();go('briefing');}
 else if(action==='practice'||action==='practice-b'){seed('incident');s.focus=action==='practice'?'a':'b';render();window.scrollTo(0,0);}
 else if(action==='opt-in'){s.ranking=!s.ranking;render();}
 else if(action==='read-all'){s.noticesRead=true;render();}
 else if(action==='recover'){s.bag='resolved';s.safety=90;s.step=4;s.feedback=feedbackFor('clear',75,80);go('feedback');}
 else if(action==='abort'){if(confirm('Завершить учебную попытку досрочно? В итоговом разборе останутся незавершённые дела.')){s.aborted=true;s.deadline=null;go('aborted');}}
}
app.addEventListener('click',event=>{const el=event.target.closest('button');if(!el||el.disabled)return;if(el.dataset.go){go(el.dataset.go);return;}if(el.dataset.select){s.selected=el.dataset.select;s.screen='action';render();document.querySelector('[data-select="'+s.selected+'"]')?.focus({preventScroll:true});return;}if(el.dataset.scope){s.scope=el.dataset.scope;render();return;}if(el.dataset.do)handle(el.dataset.do);});
app.addEventListener('change',event=>{if(event.target.name==='mode'){s.mode=event.target.value;if(s.mode==='training')s.ranking=false;render();}if(event.target.name==='policy'){s.policy=event.target.value;save();}if(event.target.id==='rank-opt'){s.ranking=event.target.checked;save();}});
render();
